Translate("zhCN", "ironforge", {
	title = "铁炉堡",
	aliases = { "铁炉堡城" },
	sections = {
		{
			title = "概述",
			text = [=[铁炉堡是{link:kingdom-of-ironforge}铁炉堡王国{/link}的首都，也是{link:dwarves}矮人{/link}最古老的城市。它开凿于{link:dun-morogh}丹莫罗{/link}一座大山的腹地，即使{link:horde}部落{/link}在鼎盛之时也未能攻下它。城市中心的{link:the-great-forge}大锻炉{/link}昼夜燃烧，为它供料的熔融{link:ginro-hearthkindle}金{/link}属之河把整座城市映成一片红金之色。锻炉周围是商贸、学术、魔法与战争的厅堂，而王座之下，还有更古老的厅堂。]=],
		},
		{
			title = "起源",
			text = [=[{link:dwarves}矮人{/link}认为铁炉堡是他们最初的家园，他们的族人在远古时代由这些山脉的岩石塑造而成。没有编年史记载它的第一批厅堂开凿于哪一年。在漫长的岁月里，所有矮人都由铁炉堡的一位至高王统治。他死后，铜须、蛮锤和黑铁三大氏族为争夺他的王位而战。铜须守住了这座城市，当{link:dark-iron-dwarves}黑铁矮人{/link}卷土重来想夺取它时，他们在城门前被击溃。]=],
		},
		{
			title = "当今",
			text = [=[国王{link:magni-bronzebeard}麦格尼·铜须{/link}在{link:high-seat}王座厅{/link}执政，铁炉堡{link:shadow-council}议会{/link}在他身旁，但并不总与他意见一致。他的大部分军队远在他乡，为{link:alliance}联盟{/link}效力。他的兄弟{link:muradin-bronzebeard}穆拉丁·铜须{/link}在北方失踪，他的兄弟{link:brann-bronzebeard}布莱恩·铜须{/link}游历四方。他的女儿茉艾拉不见了，他相信是{link:dark-iron-dwarves}黑铁{/link}皇帝带走了她。自从{link:gnomeregan}诺莫瑞根{/link}陷落以来，那里的{link:gnomes}侏儒{/link}就住在{link:tinker-town}侏儒区{/link}，他们的工匠让厅堂里充满了喧嚣。如今，王座厅下那些古老的封闭通道已被打开。有什么东西一直在惊扰领主们的陵墓，而有人发现黑铁矮人正朝它们挖掘。]=],
		},
		{
			title = "居民",
			text = [=[• {b}铜须{link:dwarves}矮人{/link}。{/b}铁匠、商人、士兵、牧师和学者遍布城中各区。
• {b}{link:gnomeregan-exiles}诺莫瑞根流亡者{/link}。{/b}大工匠{link:gelbin-mekkatorque}格尔宾·梅卡托克{/link}在{link:tinker-town}侏儒区{/link}领导着他的族人。
• {b}探险者协会。{/b}{link:explorers-league}探险者协会{/link}从{link:hall-of-explorers}探险者大厅{/link}派遣成员前往世界各地的遗迹。
• {b}{link:alliance}联盟{/link}的旅人。{/b}{link:humans}人类{/link}乘坐{link:gnomes}侏儒{/link}的地铁往来于{link:stormwind-city}暴风城{/link}与此地之间。
• {b}黑暗中的盗贼。{/b}在荒弃的洞穴中，一个名为隐秘{link:shadow-council}议会{/link}的团体密谋分取国王的财富。]=],
		},
		{
			title = "历史",
			text = [=[• {b}三锤。{/b}铜须在与同胞的争斗中守住了铁炉堡。一块保存在王室宝库中的条约石板记载了随后的和平：铜须和蛮锤签了字，{link:dark-iron-dwarves}黑铁{/link}却从未签署。
• {b}{link:second-war}第二次战争{/link}。{/b}{link:horde}部落{/link}席卷了卡兹莫丹，但铁炉堡坚守不屈。{link:dwarves}矮人{/link}加入了{link:alliance}洛丹伦联盟{/link}，一直战斗到部落被击溃。
• {b}{link:third-war}第三次战争{/link}。{/b}{link:muradin-bronzebeard}穆拉丁{/link}前往诺森德，再也没有回来。矮人把他算作死者。
• {b}{link:gnomeregan}诺莫瑞根{/link}的陷落。{/b}{link:gnomes}侏儒{/link}失去城市时，{link:magni-bronzebeard}麦格尼{/link}向他们敞开了铁炉堡的大门。
• {b}当今。{/b}{link:high-seat}王座厅{/link}下的厅堂再次敞开，王国得知它最古老的敌人一直在朝它最古老的逝者挖掘。]=],
		},
		{
			title = "山中传说",
			text = [=[• 铁炉堡的一位石匠用从残破的{link:lordaeron}洛丹伦{/link}运来的上等石料，为一位死于远方的士兵苏利·巴鲁雕刻了一座纪念碑。国王亲自支付了费用。
• 死在{link:dun-morogh}丹莫罗{/link}雪地中的巡山人会以步枪的形式回到家乡，枪托上刻着他们的名字。]=],
		},
	},
})

Translate("zhCN", "the-great-forge", {
	title = "大锻炉",
	aliases = { "大锻炉" },
	sections = {
		{
			title = "概述",
			text = [=[大锻炉占据了{link:ironforge}铁炉堡{/link}的中央大厅。熔融的{link:ginro-hearthkindle}金{/link}属从高处倾泻进巨大的熔池，周围城中的铁匠们在永不冷却的铁砧旁劳作。锻炉的热与光照到每一个城区，它的锤击声是{link:dwarves}矮人{/link}心中家的声音。商人、训练师和信使挤满了它的四周，城中的狮鹫从附近的平台上起落。城中没有别处如此繁忙，也没有别处如此受人喜爱。]=],
		},
	},
})

Translate("zhCN", "the-commons", {
	title = "商业区",
	sections = {
		{
			title = "概述",
			text = [=[商业区是{link:ironforge}铁炉堡{/link}的{link:trade-district}贸易区{/link}。这里有铁炉堡银行，城中及访客的财富在守卫下保存于此；还有宏大的拍卖行，以及旅店老板火酒的旅店。{link:alliance}联盟{/link}各族的商人来到这里，从第一个时辰到最后一个时辰，城区里讨价还价之声不绝于耳。长途跋涉的旅人会先来旅店，在温暖的炉火旁喝上一杯烈性麦酒，然后再继续上路。]=],
		},
	},
})

Translate("zhCN", "hall-of-explorers", {
	title = "探险者大厅",
	aliases = { "探险者议会" },
	sections = {
		{
			title = "概述",
			text = [=[探险者大厅是{link:explorers-league}探险者协会{/link}的大本营。它的长廊中陈列着从世界各地遗迹带回的文物，它的图书馆保存着协会的书籍和地图，它的学者们为{link:dwarves}矮人{/link}一族的真正起源争论不休。{link:high-explorer-magellas}资深探险家麦格拉斯{/link}在此主事。{link:advisor-belgrum}顾问贝尔格拉姆{/link}、{link:historian-karnik}史学家卡尼克{/link}和{link:prospector-stormpike}勘察员塔伯斯·雷矛{/link}在大厅中处理事务，来自{link:badlands}废土{/link}和{link:loch-modan}洛克莫丹{/link}挖掘场的消息最先送到这里。]=],
		},
	},
})

Translate("zhCN", "tinker-town", {
	title = "侏儒区",
	sections = {
		{
			title = "概述",
			text = [=[侏儒区是{link:magni-bronzebeard}国王麦格尼{/link}在{link:gnomeregan}诺莫瑞根{/link}陷落后赐给{link:gnomes}侏儒{/link}的城区。这里齿轮咔嗒作响，蒸汽嘶嘶喷涌，工坊里塞满了造了一半的装置。{link:gelbin-mekkatorque}大工匠梅卡托克{/link}在这里主持他的流亡朝廷。矿道地铁从侏儒区出发，深入地下直达{link:stormwind-city}暴风城{/link}，诺莫瑞根的工匠们派志愿者返回他们失落的城市，尽力抢救能救的东西。]=],
		},
	},
})

Translate("zhCN", "the-mystic-ward", {
	title = "秘法区",
	aliases = { "秘法区" },
	sections = {
		{
			title = "概述",
			text = [=[秘法区是城中献给信仰与魔法的区域。{link:holy-light}圣光{/link}的牧师在秘法大厅中侍奉，法师在周围的厅堂中研习。这里比{link:ironforge}铁炉堡{/link}的其他地方安静，远离锻炉的轰鸣，追求高深技艺的人在这里找到他们的老师。]=],
		},
	},
})

Translate("zhCN", "the-military-ward", {
	title = "军事区",
	aliases = { "军事区" },
	sections = {
		{
			title = "概述",
			text = [=[军事区是堡垒中的堡垒。它的武器大厅在穆伦·{link:stormpike-guard}雷矛{/link}的指导下训练{link:ironforge}铁炉堡{/link}的战士，他教导说，战士绝不会把后背留给敌人。国王的士兵在开赴{link:alliance}联盟{/link}前线之前在这里接受训练。这是一个艰苦的地方，在这里服役的{link:dwarves}矮人{/link}以此为荣。]=],
		},
	},
})

Translate("zhCN", "high-seat", {
	title = "王座厅",
	aliases = { "王座厅" },
	sections = {
		{
			title = "概述",
			text = [=[王座厅是{link:ironforge}铁炉堡{/link}的王座大殿，高居城市西侧的厅堂之上。{link:magni-bronzebeard}国王麦格尼·铜须{/link}在这里临朝听政，由钢铁国王卫队守护。铁炉堡的议员们为国事往来奔走，皇家历史学家在王座近旁守护着王国的记忆。大殿一侧的一扇门曾长久封闭，如今却敞开着。门后有一条路通往下方的{link:old-ironforge}旧铁炉堡{/link}。]=],
		},
	},
})

Translate("zhCN", "old-ironforge", {
	title = "旧铁炉堡",
	sections = {
		{
			title = "概述",
			text = [=[旧铁炉堡位于{link:high-seat}王座厅{/link}之下，是这座城市最古老的部分。世世代代以来，它的大门一直紧闭，很少有活着的{link:dwarves}矮人{/link}曾在那里行走。如今道路已经敞开。一条长长的小路蜿蜒穿过古老的厅堂，通往下方的洞窟，那里的{link:hall-of-thanes}领主大厅{/link}中安放着昔日伟大矮人的陵墓。这些陵墓的看守者听到宝库中传出奇怪的声响，其中的死者已开始躁动。]=],
		},
	},
})

Translate("zhCN", "magni-bronzebeard", {
