			text = [=[一块石板从{link:ironforge}铁炉堡{/link}下方的国王圣物库中被带了出来。麦格尼一眼就认出了它。那是三大氏族之战后订立的和约，订于他的先祖玛多兰的时代，玛多兰是第一位统治铁炉堡的铜须。铜须签了字，蛮锤也签了字。{link:dark-iron-dwarves}黑铁{/link}却没有。]=],
		},
		{
			title = "我们脚下",
			hint = "终结黑铁矮人对铁炉堡地下的入侵。",
			text = [=[在城市下方发现一支{link:dark-iron-dwarves}黑铁{/link}部队的消息令国王大吃一惊。听说其指挥官已死，他很高兴，立即下令封堵缺口、加固下层厅堂。他还向一位蛮锤老朋友地占师{link:earthseer-farsen}法森{/link}致以温暖的问候，并要求法森正式来访一次。]=],
		},
		{
			title = "失踪的公主",
			hint = "查明国王的女儿遭遇了什么。",
			text = [=[说起茉艾拉，麦格尼流下了眼泪。他曾派手下搜寻{link:burning-steppes}燃烧平原{/link}，找到的唯一线索指向{link:blackrock-mountain}黑石{/link}的深处。他相信她是{link:dark-iron-dwarves}黑铁{/link}皇帝达格兰·{link:ruins-of-thaurissan}索瑞森{/link}的俘虏，被他的法术所束缚，他要皇帝死。当真相传回他耳中时，情况比他担心的还要糟。茉艾拉怀着索瑞森的孩子，她传话说，{link:ironforge}铁炉堡{/link}的继承人将是一个黑铁矮人。麦格尼只能说，即使在死后，索瑞森也赢了。]=],
