Translate("zhCN", "muradin-bronzebeard", {
	title = "穆拉丁·铜须",
	subtitle = "国王的兄弟",
	found = "在诺森德失踪",
	allegiance = "铁炉堡王国",
	aliases = { "穆拉丁" },
	sections = {
		{
			title = "概述",
			text = [=[穆拉丁·铜须是{link:magni-bronzebeard}国王麦格尼{/link}的兄弟。他是{link:ironforge}铁炉堡{/link}最强大的战士之一，一个力大无穷、说话直率、心地温暖的{link:dwarves}矮人{/link}。在{link:third-war}第三次战争{/link}中，他前往冰封的大陆诺森德，再也没有回家。铁炉堡把他算作自己的死者。]=],
		},
		{
			title = "意义",
			text = [=[穆拉丁与{link:lordaeron}洛丹伦{/link}王室的联系不止于同盟。他曾是年轻的王子{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}的武艺老师，两人是朋友。这份情谊让穆拉丁见证了王子走向毁灭的最初几步。据{link:ironforge}铁炉堡{/link}的人们所信，它也让他付出了生命。]=],
		},
		{
			title = "事迹",
			text = [=[• 他为{link:alliance}联盟{/link}效力，在{link:humans}人类{/link}王国的宫廷中颇有名声。
• 他向{link:lordaeron}洛丹伦{/link}王子传授剑与锤的技艺。
• 他率领一支{link:dwarves}矮人{/link}远征队前往诺森德，寻找一把名为霜之哀伤的传奇符文剑。
• 他在冰封的荒原上与{link:arthas-menethil}阿尔萨斯{/link}并肩对抗亡灵。]=],
		},
		{
			title = "北方之旅",
			text = [=[在遇到{link:arthas-menethil}阿尔萨斯{/link}之前，穆拉丁的队伍已在诺森德寻找霜之哀伤很久了；阿尔萨斯是追随一个恐惧魔王渡海而来的。{link:dwarves}矮人{/link}与王子联手对抗亡灵。看着昔日的学生，穆拉丁越来越不安。阿尔萨斯烧毁了自己的船只，让他的手下无法回家，而对敌人的仇恨似乎已成为他活着的唯一理由。

他们终于在一个冰冻的洞穴中找到了那把剑，它被封在冰中，有守卫看护。穆拉丁读了刻在那里的警告，恳求阿尔萨斯不要碰它。王子不肯。当阿尔萨斯释放那把剑时，冰层炸裂，一块碎冰击倒了穆拉丁。阿尔萨斯拿走霜之哀伤，丢下他继续前行。]=],
		},
		{
			title = "在铁炉堡",
			text = [=[{link:dwarves}矮人{/link}们铭记穆拉丁，视他为{link:alliance}联盟{/link}的英雄和他们国王的兄弟。失去他，是{link:magni-bronzebeard}麦格尼{/link}背负的又一重担，此外还有远在他乡的军队和被{link:dark-iron-dwarves}黑铁矮人{/link}夺走的女儿。在{link:ironforge}铁炉堡{/link}的厅堂里，人们提起他的名字时满怀悲伤，也带着矮人对那些为自认正确之事而倒下的人所怀有的倔强骄傲。]=],
		},
		{
			title = "未载之事",
			text = [=[那一天之后穆拉丁的下落，{link:ironforge}铁炉堡{/link}无人知晓。他的族人相信他死在了冰中。{link:dwarves}矮人{/link}所知的编年史中没有不同的记载。]=],
		},
	},
	bonds = {
		{ id = "magni-bronzebeard", name = "麦格尼·铜须", note = "他的兄弟" },
		{ id = "brann-bronzebeard", name = "布莱恩·铜须", note = "他的兄弟" },
		{ id = "arthas-menethil", name = "阿尔萨斯·米奈希尔", note = "他的学生" },
	},
})

Translate("zhCN", "brann-bronzebeard", {
	title = "布莱恩·铜须",
	subtitle = "探险者协会的探险家",
