	allegiance = "铁炉堡王国 · 探险者协会",
	aliases = { "布莱恩" },
	sections = {
		{
			title = "概述",
			text = [=[布莱恩·铜须是{link:magni-bronzebeard}国王麦格尼{/link}最小的兄弟。麦格尼戴上了王冠，{link:muradin-bronzebeard}穆拉丁{/link}拿起了战锤，布莱恩则拿起了地图和提灯。他是{link:explorers-league}探险者协会{/link}最著名的探险家，一个宁愿睡在泰坦遗迹里也不愿睡在王室床榻上的{link:dwarves}矮人{/link}。]=],
		},
		{
			title = "意义",
			text = [=[布莱恩是协会那个伟大问题的活的化身：{link:dwarves}矮人{/link}从何而来？他用一生搜寻世界上的古老之地以寻求答案，他的名字能打开那些对较平庸的探索者紧闭的大门。他四处游历时，{link:hall-of-explorers}探险者大厅{/link}里的协会学者们继续着他的工作。]=],
		},
		{
			title = "事迹",
			text = [=[• 他为寻找{link:dwarves}矮人{/link}的起源，探索了{link:eastern-kingdoms}东部王国{/link}及更远之地的遗迹。
• 他被视为{link:explorers-league}探险者协会{/link}的领军人物之一。]=],
		},
		{
			title = "伟大的问题",
			text = [=[驱使布莱恩的问题，正是整个协会都在追问的问题：{link:dwarves}矮人{/link}真的是由泰坦用岩石塑造的吗？在他缺席期间，他的同僚们比以往任何时候都更接近答案。他们从{link:uldaman}奥达曼{/link}深处带回了关于泰坦造物的记录，而这些记录指向南方沙漠中更宏大的宝库。这正是布莱恩为之献出一生的那种发现。]=],
		},
		{
