	},
})

Translate("zhCN", "gelbin-mekkatorque", {
	title = "格尔宾·梅卡托克",
	subtitle = "大工匠，侏儒之王",
	found = "铁炉堡，侏儒区",
	hint = "到侏儒区寻找大工匠。",
	allegiance = "诺莫瑞根流亡者 · 联盟",
	aliases = { "梅卡托克", "大工匠梅卡托克", "格尔宾", "大工匠格尔宾·梅卡托克" },
	sections = {
		{
			title = "概述",
			text = [=[格尔宾·梅卡托克是{link:gnomes}侏儒{/link}的大工匠，一个失去了王国的民族的国王。当{link:gnomeregan}诺莫瑞根{/link}鼎盛之时，他在那里执政。如今他在{link:tinker-town}侏儒区{/link}的一间工坊里执政，作为{link:dwarves}矮人{/link}的客人，他的族人大多已死去、中毒或流散四方。他没有失去智慧，也没有失去意志。他决意回家。]=],
		},
		{
			title = "意义",
			text = [=[梅卡托克把{link:gnomes}侏儒{/link}凝聚在一起。没有他，流亡者只会是一群难民。有了他，他们依然是一个民族，在{link:alliance}联盟{/link}各族中占有一席之地，并从未放弃对自己城市的权利。]=],
		},
		{
			title = "事迹",
			text = [=[• 他作为大工匠领导{link:gnomeregan}诺莫瑞根{/link}的{link:gnomes}侏儒{/link}。
• 当{link:troggs}石腭怪{/link}在城市下方崛起时，他在一场孤注一掷的清洗中把侏儒自己的技艺用来对付它们，城市因此被污染。
• 他带领幸存者来到{link:ironforge}铁炉堡{/link}，让{link:tinker-town}侏儒区{/link}成为他们的家园。
• 他派志愿者返回诺莫瑞根，取回遗留下来的东西，并打击占据城市的叛徒。]=],
		},
		{
			title = "城市的陷落",
			text = [=[没有编年史记载{link:troggs}石腭怪{/link}从{link:gnomeregan}诺莫瑞根{/link}地下深处钻出来的年份。它们数量庞大，城市无法将它们击退。梅卡托克选择用{link:gnomes}侏儒{/link}自己制造的武器清除它们。武器杀死了石腭怪，却也杀死了大量侏儒，并让整座城市浸透了毒素。许多幸存者变成了病弱而痴呆的麻风侏儒。其余的人逃进了{link:dun-morogh}丹莫罗{/link}的雪原。]=],
		},
		{
			title = "流亡朝廷",
			text = [=[在{link:tinker-town}侏儒区{/link}，大工匠的族人从未停止工作。工匠大师欧沃{link:spark-nilminer}斯巴克{/link}希望修好他可怜的尖端机器人，它的心智在陷落中被颠倒了。机械大师卡斯派普组织队伍从城市的终端中找回重要的记录。科罗莫特·钢尺需要那些逃亡时没人记得带走的零件。每一次这样的任务都是重返{link:gnomeregan}诺莫瑞根{/link}的一小步，梅卡托克对它们都予以鼓励。]=],
		},
	},
	chapters = {
		{
			title = "大背叛",
			hint = "击倒统治诺莫瑞根的叛徒。",
			text = [=[梅卡托克曾信任{link:mekgineer-thermaplugg}希科·瑟玛普拉格{/link}。他从未想过瑟玛普拉格会背叛他和整个{link:gnomes}侏儒{/link}族，至今仍不明白为什么，因为权力和财富迟早都会落到瑟玛普拉格手中。如今这个叛徒坐在废墟之中，成了一无所有之王。当瑟玛普拉格倒下的消息传来时，梅卡托克允许自己开了一个冷峻的玩笑，随后便把心思转向侏儒夺回城市的那一天。]=],
		},
	},
	mentions = {
		{ text = "数据营救" },
		{ text = "拯救尖端机器人的大脑！" },
		{ text = "重要的人造物" },
	},
	bonds = {
		{ id = "mekgineer-thermaplugg", name = "机械师瑟玛普拉格", note = "叛徒" },
		{ id = "magni-bronzebeard", name = "麦格尼·铜须", note = "他的东道主和盟友" },
		{ id = "razzle-sprysprocket", name = "拉兹·滑链", note = "他寻求治愈之法的族人之一" },
	},
})

Translate("zhCN", "royal-historian-archesonus", {
	title = "皇家历史学家阿克瑟努斯",
	subtitle = "铁炉堡皇家历史学家",
	found = "王座厅，王座旁",
	hint = "与在王座旁守护王国记忆的历史学家交谈。",
	allegiance = "铁炉堡王国",
	aliases = { "阿克瑟努斯" },
	sections = {
		{
			title = "概述",
			text = [=[皇家历史学家阿克瑟努斯在{link:magni-bronzebeard}国王麦格尼{/link}的王座旁守护着{link:ironforge}铁炉堡{/link}的记忆。任何人都可以向她询问王国的历史。她讲述时最为凝重的，是{link:dark-iron-dwarves}黑铁矮人{/link}的故事，以及那座被焚毁的城市{link:ruins-of-thaurissan}索瑞森{/link}。]=],
		},
		{
			title = "意义",
			text = [=[阿克瑟努斯是{link:ironforge}铁炉堡{/link}往昔的声音。{link:dwarves}矮人{/link}是一个记忆悠长的民族，而在{link:high-seat}王座厅{/link}，这份记忆有一位守护者。她对{link:dark-iron-dwarves}黑铁矮人{/link}的了解已变得至关重要，因为王国的宿敌又开始行动了。]=],
		},
		{
			title = "事迹",
			text = [=[• 她向来到{link:high-seat}王座厅{/link}的人讲授{link:ironforge}铁炉堡{/link}的历史。
• 她派搜寻者前往{link:burning-steppes}燃烧平原{/link}的{link:ruins-of-thaurissan}索瑞森废墟{/link}，解读那里留下的遗物。]=],
		},
	},
	chapters = {
		{
			title = "索瑞森的故事",
			hint = "向皇家历史学家询问黑铁矮人的历史。",
			text = [=[阿克瑟努斯从很久以前讲起，那时{link:dark-iron-dwarves}黑铁矮人{/link}有一座属于自己的城市。{link:ruins-of-thaurissan}索瑞森{/link}坐落在一片青翠的土地上，那片土地如今是{link:burning-steppes}燃烧平原{/link}，而在那些日子里，{link:dwarves}矮人{/link}各氏族之间相互征战。后来一场可怕的爆炸摧毁了它，方圆数里的土地都被烧成了灰烬。她承认，是什么引发了爆炸，没有历史学家能说清。幸存的黑铁矮人进入山中，重新开始。{link:blackrock-mountain}黑石{/link}塔从灰烬中崛起，{link:searing-gorge}灼热峡谷{/link}的{link:the-cauldron}大熔炉{/link}也被筑起了防御。不久便有传言说，一股远古的邪恶从内部统治着黑铁王国。她的故事在当下结束。黑铁矮人一年比一年更频繁地出现在地面上。他们在{link:badlands}废土{/link}建起了堡垒，派大批人马进入{link:uldaman}奥达曼{/link}，甚至袭击了{link:loch-modan}洛克莫丹{/link}的水坝。]=],
		},
		{
			title = "阴燃的废墟",
			hint = "解读索瑞森的遗物，把它们的记忆带回家。",
			text = [=[废墟之城的遗物承载着记忆，触碰它们的人会把记忆留在心中。一个纯粹由火焰构成的生物。八个举行仪式的{link:dark-iron-dwarves}黑铁矮人{/link}。最后只剩其中一人，独自跪在七具尸体之间，面对一根火柱。阿克瑟努斯听了这些记忆，说它们解释了许多事情，而且还有更多需要了解。]=],
		},
	},
	mentions = {
		{ text = "{link:ruins-of-thaurissan}索瑞森{/link}的阴燃废墟" },
	},
	bonds = {
		{ id = "magni-bronzebeard", name = "麦格尼·铜须", note = "她的国王" },
	},
})

